100:    commit(g, { grow = true, protect, keep = [] }) {
113:        if (protect?.has(p.join(","))) { refused++; continue; }
173: *   keep         [{from:[x,y,z], to:[x,y,z]}] never written; protect: Set "x,y,z" (default: the grid's functional cells)
